insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('uba', 'Universidad de Buenos Aires', 'UBA', 'universidad', 'publica', 'https://www.uba.ar', 'verificado', '2026-11-10', array['Listado de carreras tomado de las páginas por facultad de uba.ar.','La página de Odontología en uba.ar no lista carreras: pendiente consultar odon.uba.ar.','Sedes de dictado, CBC, duración, títulos y modalidad: pendientes.']::text[]);
insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('utn-ba', 'Universidad Tecnológica Nacional — Facultad Regional Buenos Aires', 'UTN.BA', 'universidad', 'publica', 'https://www.frba.utn.edu.ar', 'verificado', '2026-11-10', array['El sitio frba.utn.edu.ar no respondió durante la verificación del 10/11/2026.','Las ingenierías se tomaron de la tabla oficial de carreras acreditadas por CONEAU publicada por UTN (rectorado). La tabla nombra la carrera abreviada (p. ej. ''Civil''); el nombre completo se reconstruyó como ''Ingeniería …'' y debe confirmarse en frba.utn.edu.ar.','Ingeniería Naval figura como ''INGRESA'' (sin resolución de acreditación).','Puede haber más oferta (licenciaturas, tecnicaturas) no incluida en esa tabla: pendiente.','Sedes, duración, títulos, modalidad e ingreso: pendientes.']::text[]);
insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('unsam', 'Universidad Nacional de San Martín', 'UNSAM', 'universidad', 'publica', 'https://www.unsam.edu.ar', 'pendiente', '2026-11-10', array['El sitio oficial rechazó las consultas automatizadas el 10/11/2026 (unsam.edu.ar/oferta/carreras/ y otras páginas).','La página de listado de carreras (unsam.edu.ar/estudiantes/guia/listado-carreras.php) solo muestra tipos de título por escuela, sin nombres: no alcanza para cargar carreras.','Escuelas e institutos con oferta de grado o pregrado según esa página: Escuela de Ciencia y Tecnología, Escuela de Economía y Negocios, Escuela de Humanidades, Escuela de Política y Gobierno, Escuela IDAES, Instituto de Calidad Industrial, Instituto de Rehabilitación y Movimiento, Instituto Dan Beninson, Instituto de Tecnología Prof. Jorge Sabato, OESPU, Escuela de Arte y Patrimonio, Escuela de Hábitat y Sostenibilidad, Escuela de Bio y Nanotecnologías.','Verificación manual necesaria antes de incluir carreras.']::text[]);
insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('unlam', 'Universidad Nacional de La Matanza', 'UNLaM', 'universidad', 'publica', 'https://www.unlam.edu.ar', 'pendiente', '2026-11-10', array['El sitio oficial rechazó las consultas automatizadas el 10/11/2026.','No se cargan carreras desde fuentes no oficiales. Verificación manual necesaria.']::text[]);
insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('untref', 'Universidad Nacional de Tres de Febrero', 'UNTREF', 'universidad', 'publica', 'https://www.untref.edu.ar', 'verificado', '2026-11-10', array['Listado de untref.edu.ar/carreras. La página no indica modalidad (presencial o virtual), duración ni título.','La página de sedes solo muestra direcciones de rectorado y posgrado; las sedes de dictado por carrera están pendientes.']::text[]);
