insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('ub', 'Universidad de Belgrano', 'UB', 'universidad', 'privada', 'https://www.ub.edu.ar', 'verificado', '2026-11-10', array['Listado de ub.edu.ar/distribucion-carreras-de-grado. Los encabezados son áreas del sitio, no necesariamente facultades.','Las tecnicaturas universitarias están en otra página (ub.edu.ar/distribucion-tecnicaturas-universitarias): pendientes.','Modalidad, sede por carrera y duración: pendientes.']::text[]);
