insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('up', 'Universidad de Palermo', 'UP', 'universidad', 'privada', 'https://www.palermo.edu', 'verificado', '2026-11-10', array['Listado de palermo.edu/indice-carreras-grado.html. Algunas carreras aparecen en más de una facultad.','La página separa modalidad online y presencial/combinada, pero la herramienta de verificación no conservó qué carrera va en cada una: modalidad pendiente.','Bajo ''Facultad de Arquitectura'' la página no lista carreras; Arquitectura figura en Diseño y Comunicación.','La página de sedes indica 10 sedes pero lista 9; sede por carrera pendiente.']::text[]);
