insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('uade', 'Universidad Argentina de la Empresa', 'UADE', 'universidad', 'privada', 'https://www.uade.edu.ar', 'verificado', '2026-11-10', array['Listado del Fact Sheet 2026 oficial de UADE (PDF en uade.edu.ar). Las dobles titulaciones no están incluidas en ese documento.','Arquitectura figura tanto en Facultad de Arquitectura y Diseño como en Facultad de Arquitectura y Urbanismo.','El sitio da dos numeraciones distintas para la sede Belgrano; se usa la del Fact Sheet.','Solo Gestión de Tecnología de la Información indica modalidad (presencial y online). Resto: pendiente. Sede por carrera: pendiente.']::text[]);
