insert into public.institutions (slug, name, short_name, kind, sector, website, status, verified_at, notes) values ('utdt', 'Universidad Torcuato Di Tella', 'UTDT', 'universidad', 'privada', 'https://www.utdt.edu', 'verificado', '2026-11-10', array['Listado de utdt.edu/ingreso (12 carreras de grado). La página no antepone ''Licenciatura en'' ni indica duración o título: se guardan los nombres tal como aparecen.','Ingeniería Industrial se anuncia como nueva carrera con inicio en marzo de 2027.','Ciencias Sociales tiene orientaciones: Comunicación y Periodismo, Desarrollo Social y Económico, Sociedad y Mercado, Historia y Cultura, Arte.','La página menciona ''nuevas concentraciones'' (Tecnología Digital, Inteligencia Artificial, Negocios Digitales) que no se cargan como carreras.']::text[]);
